                  fontWeight: '600',
                  color: 'white',
                  cursor: (isStreaming || !primeNumber.trim()) ? 'not-allowed' : 'pointer',
                  opacity: (isStreaming || !primeNumber.trim()) ? 0.5 : 1,
                  transform: 'scale(1)',
                  transition: 'transform 0.2s ease'
                }}
                onMouseEnter={(e) => {
                  if (!isStreaming && primeNumber.trim()) e.target.style.transform = 'scale(1.05)';
                }}
                onMouseLeave={(e) => e.target.style.transform = 'scale(1)'}
              >
                {isStreaming ? 'Testing...' : 'Test Prime'}
              </button>
            </div>

            {isStreaming && (
              <div style={{ marginBottom: '1.5rem', textAlign: 'center' }}>
                <button
                  onClick={stopStream}
                  style={{
                    padding: '0.5rem 1rem',
                    background: 'linear-gradient(to right, #dc2626, #ea580c)',
                    border: 'none',
                    borderRadius: '0.5rem',
                    fontWeight: '600',
                    color: 'white',
                    cursor: 'pointer',
                    fontSize: '0.875rem'
                  }}
                >
                  Stop Test
                </button>
              </div>
            )}

            {streamLogs.length > 0 && (
              <div style={{
                background: 'rgba(0, 0, 0, 0.3)',
                borderRadius: '1rem',
                padding: '1.5rem',
                border: '1px solid rgba(255, 255, 255, 0.1)'
              }}>
                <div style={{ 
                  display: 'flex', 
                  justifyContent: 'space-between', 
                  alignItems: 'center', 
                  marginBottom: '1rem' 
                }}>
                  <h3 style={{ fontSize: '1.25rem', fontWeight: '600' }}>Miller-Rabin Test Results</h3>
                  {isStreaming && (
                    <div style={{ display: 'flex', alignItems: 'center' }}>
                      <div style={{
                        width: '0.75rem',
                        height: '0.75rem',
                        background: '#4ade80',
                        borderRadius: '50%',
                        marginRight: '0.5rem',
                        animation: 'pulse 2s infinite'
                      }}></div>
                      <span style={{ color: '#4ade80' }}>Testing...</span>
                    </div>
                  )}
                </div>
                <div style={{
                  maxHeight: '16rem',
                  overflowY: 'auto',
                  fontFamily: 'monospace',
                  fontSize: '0.875rem'
                }}>
                  {streamLogs.map((log, index) => (
                    <div key={index} style={{ color: '#d1d5db', marginBottom: '0.5rem' }}>
                      {formatLogEntry(log)}
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Question Cards */}
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))',
          gap: '2rem'
        }}>
          {questions.map((question) => (
            <div
              key={question.id}
              onClick={() => setSelectedCard(question)}
              style={{
                cursor: 'pointer',
                transform: 'scale(1)',
                transition: 'transform 0.3s ease',
                background: `linear-gradient(135deg, ${question.color.includes('purple') ? '#9333ea, #ec4899' : 
                  question.color.includes('blue') ? '#2563eb, #06b6d4' :
                  question.color.includes('green') ? '#059669, #10b981' :
                  question.color.includes('red') ? '#dc2626, #f97316' :
                  question.color.includes('indigo') ? '#4f46e5, #9333ea' :
                  question.color.includes('yellow') ? '#d97706, #f97316' :
                  '#14b8a6, #10b981'})`,
                borderRadius: '1rem',
                padding: '1px'
              }}
              onMouseEnter={(e) => e.target.style.transform = 'scale(1.05)'}
              onMouseLeave={(e) => e.target.style.transform = 'scale(1)'}
            >
              <div style={{
                background: 'rgba(17, 24, 39, 0.8)',
                borderRadius: '1rem',
                padding: '1.5rem',
                height: '100%',
                backdropFilter: 'blur(10px)'
              }}>
                <div style={{ fontSize: '1.875rem', marginBottom: '1rem' }}>🔢</div>
                <h3 style={{ fontSize: '1.25rem', fontWeight: 'bold', marginBottom: '0.75rem' }}>
                  {question.title}
                </h3>
                <p style={{ 
                  color: '#d1d5db', 
                  fontSize: '0.875rem', 
                  lineHeight: '1.5',
                  marginBottom: '1rem'
                }}>
                  {question.description}
                </p>
                <div style={{ textAlign: 'right' }}>
                  <span style={{ 
                    fontSize: '1.5rem', 
                    opacity: 0.5,
                    transition: 'opacity 0.3s ease'
                  }}>
                    →
                  </span>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Add CSS animation for pulse effect */}
      <style jsx>{`
        @keyframes pulse {
          0%, 100% {
            opacity: 1;
          }
          50% {
            opacity: 0.5;
          }
        }
      `}</style>
    </div>
  );
}

export default App;
